namespace Invoicing;

/// <summary>Resolves the VAT due for a net amount given account and jurisdiction.</summary>
public sealed class VatResolver
{
    private static readonly IReadOnlyDictionary<string, decimal> CountryRates =
        new Dictionary<string, decimal>(StringComparer.OrdinalIgnoreCase)
        {
            ["GB"] = 0.20m,
            ["DE"] = 0.19m,
            ["FR"] = 0.20m,
            ["IE"] = 0.23m
        };

    public decimal Resolve(Account account, decimal net, string countryCode)
    {
        if (net <= 0m)
            return 0m;

        var baseRate = GetCountryRate(countryCode);
        var adjustedRate = AdjustRate(baseRate, account.Kind, net);
        return net * adjustedRate;
    }

    private static decimal GetCountryRate(string countryCode) =>
        countryCode != null && CountryRates.TryGetValue(countryCode, out var rate)
            ? rate
            : 0m;

    private static decimal AdjustRate(decimal rate, AccountKind kind, decimal net)
    {
        if (kind == AccountKind.Government)
            return 0m;

        if (kind == AccountKind.Business && net > 10_000m)
            rate *= 0.5m;

        return rate > 0m && net > 100_000m
            ? Math.Min(rate, 0.15m)
            : rate;
    }
}
